'use client'

import { demoUrl } from '@/lib/demoOrigin'
import { cn } from '@/lib/utils'

export type LiquidButtonsProps = {
  /** URL do demo (build estático). Padrão: CDN do catálogo / local em localhost. */
  src?: string
  /** Altura do preview. */
  height?: number | string
  title?: string
  className?: string
}

/**
 * Preview dos Liquid Buttons (Three.js): botões de vidro com refração,
 * ripple na base e barrel roll 360° no clique.
 * Demo estático em public/liquid-buttons (repo kunal-chaudhary-design/liquid-buttons).
 */
export function LiquidButtons({
  src,
  height = 480,
  title = 'Liquid Buttons',
  className,
}: LiquidButtonsProps) {
  const demoSrc = src ?? demoUrl('/liquid-buttons/')
  return (
    <div
      className={cn('relative w-full overflow-hidden rounded-2xl border bg-[#e7e8e5]', className)}
      style={{ height }}
    >
      <iframe
        title={title}
        src={demoSrc}
        className="absolute inset-0 h-full w-full border-0"
        loading="lazy"
        allow="accelerometer; gyroscope"
      />
    </div>
  )
}

/** Origem dos demos estáticos (HTML/CSS/JS) publicados no catálogo. */
export const DEMO_ORIGIN = 'https://componentes-indol.vercel.app'

/**
 * Resolve URL de demo embutido (iframe / assets).
 * - No catálogo local (localhost), usa caminho relativo para hot-reload dos demos.
 * - Em projetos consumidores (API/mirror), aponta ao CDN do catálogo para
 *   garantir estilização e efeitos mesmo antes de copiar `public/`.
 */
export function demoUrl(path: string) {
  const clean = path.startsWith('/') ? path : `/${path}`
  if (typeof window !== 'undefined') {
    const host = window.location.hostname
    if (host === 'localhost' || host === '127.0.0.1') {
      return clean
    }
  }
  return `${DEMO_ORIGIN}${clean}`
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
